def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])

    # Find homogeneous row lines (all cells in row equal)
    sep_rows = {}
    for r in range(H):
        if all(grid[r][c] == grid[r][0] for c in range(W)):
            sep_rows[r] = grid[r][0]

    # Find homogeneous column lines (all cells in column equal)
    sep_cols = {}
    for c in range(W):
        if all(grid[r][c] == grid[0][c] for r in range(H)):
            sep_cols[c] = grid[0][c]

    # Initialize result with placeholder
    result = [[0] * W for _ in range(H)]
    visited = [[False] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            # Skip separator lines - they stay as-is
            if r in sep_rows or c in sep_cols:
                result[r][c] = grid[r][c]
                continue

            # Process non-separator, non-zero cells
            if grid[r][c] != 0 and not visited[r][c]:
                # BFS to find connected component
                component = []
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop(0)
                    component.append((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            # Don't cross separator lines and skip already visited
                            if not (nr in sep_rows or nc in sep_cols) and \
                               not visited[nr][nc] and grid[nr][nc] != 0:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Find marker in block
                vals = [grid[cr][cc] for cr, cc in component]
                counts = Counter(vals)

                if len(counts) == 1:
                    # All same value, keep as-is (probably background 5)
                    fill = counts.most_common(1)[0][0]
                else:
                    # Has marker and background
                    bg = max(counts.items(), key=lambda x: x[1])[0]
                    marker = [k for k in counts.keys() if k != bg][0]
                    fill = marker + 5

                # Fill entire component
                for cr, cc in component:
                    result[cr][cc] = fill

    return result
